    eventi.push(nome + ': ho creato in «Post» le cartelle di servizio ' + mancanti.map((n) => '«' + (n === 'pronti' ? 'Pronti' : n) + '»').join(', ') + '.');
    return; // si lavora dal prossimo giro, con le cartelle pronte
  }
