  for (const f of figliDi(cartelle._in_lavorazione)) {
    const p = f.appProperties || {};
    const t = Date.parse(p.ag_prenotato_il || '') || Date.parse(f.modifiedTime || '') || 0;
    if (ora - t < BLOCCO) continue;
    const tentativi = intero(p.ag_tentativi, 0) + 1;
    const definitivo = tentativi >= MAX_TENTATIVI;
    azioni.push({ azione_giro: 'sposta', cliente: cl.cliente, file_id: f.id, aggiungi: definitivo ? cartelle._da_sistemare : cartelle.post, togli: cartelle._in_lavorazione,
      corpo: { appProperties: { ag_prenotato_da: null, ag_prenotato_il: null, ag_tentativi: String(tentativi), ag_riprova_dopo: isoAdesso(ora) } } });
    eventi.push(nome + ': «' + f.name + '» era fermo in lavorazione da ' + Math.round((ora - t) / 60000) + ' minuti; ' +
      (definitivo ? 'dopo ' + tentativi + ' tentativi l\'ho messo in Post/_da_sistemare.' : 'l\'ho rimesso in «Post» (tentativo ' + tentativi + ' di ' + MAX_TENTATIVI + ').'));
  }

  // 2) candidati: foto sciolte (= post) e sottocartelle (= carosello)
  const candidati = [];
  for (const f of figli) {
    if (eCartella(f)) continue;
    if (eFoto(f)) {
      if (Number(f.size) > MAX_BYTE) { daSistemare(cl, f, 'la foto pesa più di ' + numero(CFG.MAX_MB_FOTO, 40) + ' MB', cartelle); continue; }
      candidati.push({ tipo: 'file', voce: f, foto: [f], brief: null });
      continue;
    }
    if (eIgnorabile(f)) continue;
    const mime = String(f.mimeType || '');
    const perche = /heic|heif/i.test(mime + f.name) ? 'è una foto HEIC dell\'iPhone: esportala in JPEG'
      : mime.startsWith('video/') ? 'è un video: i video vanno nella cartella «Reel»'
        : 'non è una foto che so lavorare (vanno bene JPEG, PNG, WebP, TIFF, AVIF)';
    daSistemare(cl, f, perche, cartelle);
  }
  for (const c of figli) {
    if (!eCartella(c) || CARTELLE_DI_SERVIZIO.includes(norm(c.name)) || testo(c.name).startsWith('_')) continue;
    const contenuto = figliDi(c.id);
    const foto = contenuto.filter(eFoto).sort(ordineNaturale);
    const brief = contenuto.find(eBrief) || null;
    const altri = contenuto.filter((f) => !eFoto(f) && f !== brief && !eIgnorabile(f));
    if (altri.length) { daSistemare(cl, c, 'dentro ci sono file che non sono foto (' + altri.slice(0, 3).map((f) => f.name).join(', ') + ')', cartelle); continue; }
