const elenchiPost = $('Elenca la cartella Post').all().map((i) => i.json || {});
const elenchiSotto = $input.all().map((i) => i.json || {});

const QUIETE = Math.max(1, numero(CFG.MINUTI_QUIETE, 10)) * 60000;
