  azioni.push({ azione_giro: 'sposta', cliente: cl.cliente, file_id: f.id, aggiungi: cartelle._da_sistemare, togli: cartelle.post,
    corpo: { appProperties: { ag_motivo: taglia(motivo, 90), ag_spostato_il: isoAdesso(ora) } } });
  eventi.push(cl.scheda.nome_locale + ': ho messo «' + f.name + '» in Post/_da_sistemare — ' + motivo + '. Sistemalo e rimettilo in «Post».');
};

clienti.forEach((cl, i) => {
  const nome = cl.scheda.nome_locale;
  const P = elenchiPost[i] || {};
  const S = elenchiSotto[i] || {};
  if (cl.errore_drive || P.error || S.error) {
    problemi.push(nome + ': non riesco a leggere la cartella Drive (' + (cl.errore_drive || (P.error ? erroreTesto(P.error, P.details) : erroreTesto(S.error, S.details))) + ').');
    return;
  }
  if (!cl.post_id) {
    azioni.push({ azione_giro: 'crea_cartella', cliente: cl.cliente, nome: 'Post', dentro: cl.cartella_drive });
    eventi.push(nome + ': ho creato la cartella «Post». Le foto da trasformare in post vanno lì.');
    return;
  }
  if (P.nextPageToken || S.nextPageToken) problemi.push(nome + ': nella cartella Post ci sono più di 1000 file, guardo solo i primi.');
  const figli = Array.isArray(P.files) ? P.files.filter((f) => !f.trashed) : [];
  const sotto = Array.isArray(S.files) ? S.files.filter((f) => !f.trashed) : [];
  const cartelle = { post: cl.post_id };
  for (const nomeServizio of CARTELLE_DI_SERVIZIO) {
    const c = figli.find((f) => eCartella(f) && norm(f.name) === nomeServizio);
    if (c) cartelle[nomeServizio === 'pronti' ? 'pronti' : nomeServizio] = c.id;
  }
  const mancanti = CARTELLE_DI_SERVIZIO.filter((n) => !cartelle[n]);
  if (mancanti.length) {
    for (const n of mancanti) azioni.push({ azione_giro: 'crea_cartella', cliente: cl.cliente, nome: n === 'pronti' ? 'Pronti' : n, dentro: cl.post_id });
    eventi.push(nome + ': ho creato in «Post» le cartelle di servizio ' + mancanti.map((n) => '«' + (n === 'pronti' ? 'Pronti' : n) + '»').join(', ') + '.');
    return; // si lavora dal prossimo giro, con le cartelle pronte
  }
