    eventi.push(nome + ': «' + f.name + '» era fermo in lavorazione da ' + Math.round((ora - t) / 60000) + ' minuti; ' +
      (definitivo ? 'dopo ' + tentativi + ' tentativi l\'ho messo in Post/_da_sistemare.' : 'l\'ho rimesso in «Post» (tentativo ' + tentativi + ' di ' + MAX_TENTATIVI + ').'));
  }

