      azioni.push({ azione_giro: 'segna', cliente: cl.cliente, file_id: k.voce.id, corpo: { appProperties: { ag_firma: firma, ag_visto: isoAdesso(ora) } } });
      continue;
    }
    const visto = Date.parse(p.ag_visto || '') || ora;
