    const ultimaModifica = Math.max(0, ...date);
    if (ora - visto < QUIETE || ora - ultimaModifica < QUIETE) continue;
    pronti.push({ visto, voce: {
      azione: 'lavora', azione_giro: 'lavora', cliente: cl.cliente, scheda: cl.scheda, cartelle,
      materiale: {
        tipo: k.tipo, id: k.voce.id, nome: k.voce.name, descrizione: testo(k.voce.description), firma,
        tentativi: intero(p.ag_tentativi, 0), brief_txt_id: k.brief ? k.brief.id : '',
        foto: k.foto.map((f) => ({ id: f.id, name: f.name, mimeType: f.mimeType, size: f.size || '', md5Checksum: f.md5Checksum || '' })),
      },
    } });
  }
});

pronti.sort((a, b) => a.visto - b.visto);
